syntax:
// The DELETE OPERATOR (the expression)
delete pw;           // Does: destruct + deallocate
delete[] pa;         // Array form

// OPERATOR DELETE (the deallocation function)
void operator delete(void* ptr) noexcept;           // Global deallocator
void operator delete(void* ptr, size_t size) noexcept;  // Sized deallocation (C++14)
void Widget::operator delete(void* ptr) noexcept;   // Class-specific

// What the delete operator does internally:
delete pw;
// Expands to approximately:
if (pw != nullptr) {
  pw->~Widget();              // Step 1: destruct
  operator delete(pw);        // Step 2: deallocate
}

// Custom operator delete (overloading the deallocator)
void Widget::operator delete(void* ptr) noexcept {
  free(ptr);
}

// Using just operator delete (no destruction)
pw->~Widget();              // Manually call destructor first
operator delete(pw);        // Then deallocate

// Common pitfall - wrong order causes undefined behavior:
operator delete(pw);  // WRONG: deallocates first
pw->~Widget();        // UNDEFINED BEHAVIOR: destroys freed memory

// Matching pairs (must match allocation/deallocation):
void* operator new(size_t size);
void operator delete(void* ptr) noexcept;

void* operator new[](size_t size);
void operator delete[](void* ptr) noexcept;

code_example:
#include <iostream>
#include <cstdlib>

class Resource {
    int* data;
    int id;
public:
    Resource(int i) : data(new int(100)), id(i) {
        std::cout << "Resource " << id << " constructed\n";
    }

    ~Resource() {
        std::cout << "Resource " << id << " destructor called\n";
        delete data;  // Clean up internal resource
    }

    void* operator new(size_t size) {
        std::cout << "operator new: allocating " << size << " bytes\n";
        return malloc(size);
    }

    void operator delete(void* ptr) noexcept {
        std::cout << "operator delete: deallocating memory\n";
        free(ptr);
    }
};

int main() {
    std::cout << "=== Using delete operator (does both destruction + deallocation) ===\n";
    Resource* r1 = new Resource(1);
    delete r1;  // Calls: destructor, then operator delete

    std::cout << "\n=== Manual destruction and deallocation ===\n";
    Resource* r2 = new Resource(2);

    // Manual approach (what delete does internally)
    r2->~Resource();        // Step 1: explicit destructor call
    operator delete(r2);    // Step 2: deallocate memory

    std::cout << "\n=== WRONG: Deallocation before destruction (undefined behavior) ===\n";
    Resource* r3 = new Resource(3);
    // operator delete(r3);    // WRONG: deallocates first
    // r3->~Resource();        // UNDEFINED BEHAVIOR: uses freed memory
    // Commented out to avoid crash
    delete r3;  // Correct way

    return 0;
}
